size_t hq_theme_count(void) { return sizeof(themes)/sizeof(themes[0]); }
const hq_theme *hq_theme_at(size_t i) { return i<hq_theme_count() ? &themes[i]:NULL; }
const hq_theme *hq_theme_named(const char *name) {
    if(!name) return NULL;
    for(size_t i=0;i<hq_theme_count();++i) if(!strcmp(name,themes[i].name)) return &themes[i];
    return NULL;
}
hq_color hq_heat(const hq_theme *t,double value) { return t ? hq_gradient(t->heat,t->heat_count,value):0; }
hq_color hq_series(const hq_theme *t,size_t i) { return t && t->graph_count ? t->graph[i%t->graph_count]:0; }
